(() => {
  'use strict';
  const C = window.LearningCore, lists = window.VOCAB.lists;
  const all = lists.flatMap(l => l.words), byId = new Map(all.map(w => [w.id, w])), known = new Set(byId.keys());
  const KEY = 'reading30.progress.v1';
  const esc = value => String(value ?? '').replace(/[&<>"']/g, s => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
  let state, saveError = '', loadError = '';
  try { const saved = localStorage.getItem(KEY); state = saved ? C.validate(JSON.parse(saved), known) : C.fresh(); }
  catch (e) { state = C.fresh(); loadError = '未能读取原有进度，请先导入备份。为保护原数据，本次不会自动覆盖保存。'; }
  let page = 'home', selectedList = 1, searchText = '', savedView = 'all', audio = null, audioToken = 0, toastTimer;
  const app = document.getElementById('app');
  function persist() { if (loadError) return; try { localStorage.setItem(KEY, JSON.stringify(state)); saveError = ''; } catch(e) { saveError = '当前浏览器无法保存进度，请在设置中导出备份。'; } }
  function notify(message) { let t = document.getElementById('toast'); if (!t) { t = document.createElement('div'); t.id = 'toast'; t.className = 'toast'; t.setAttribute('role','status'); document.body.append(t); } t.textContent = message; clearTimeout(toastTimer); toastTimer = setTimeout(() => t.remove(), 4500); }
  const icon = (name) => { const paths = {home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M12 5c-3-2-7-2-10-1v15c3-1 7-1 10 1m0-15c3-2 7-2 10-1v15c-3-1-7-1-10 1V5',review:'M3 10a9 9 0 1 1 2 8M3 4v6h6M12 7v5l3 2',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9 1.1-6.2L3 9.6l6.2-.9Z',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',sound:'M11 4 5 9H2v6h3l6 5V4m5 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L19 6'}; return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.book}"/></svg>`; };
  function dueWords() { return all.filter(w => C.isDue(state,w.id)); }
  function pendingShort() { return all.filter(w=>state.words[w.id]?.delayedDueAt>Date.now()).sort((a,b)=>state.words[a.id].delayedDueAt-state.words[b.id].delayedDueAt); }
  function dueLabel(id) { const r=C.reviewInfo(state,id); if(r.isShortDue)return '现在 · 延迟回想'; if(r.isDayDue)return r.overdueDays?'已逾期 '+r.overdueDays+' 天 · 优先复习':'今天复习'; if(r.shortMinutesUntil!==null)return '约 '+r.shortMinutesUntil+' 分钟后 · 延迟回想'; if(!r.due)return '尚未安排'; if(r.daysUntil===1)return '明天复习'; return r.daysUntil+' 天后复习 · '+r.due.slice(5); }
  function reviewNudge() { const due=dueWords().length, pending=pendingShort(); if(due)return `<section class="upcoming-review"><h3>现在有 ${due} 个词可以复测</h3><p>先回想旧词，再继续今天的新词。中文和选项会先隐藏。</p>${button('开始到期复习','nav','data-page="review"','secondary')}</section>`; if(pending.length){const at=state.words[pending[0].id].delayedDueAt,minutes=Math.max(1,Math.ceil((at-Date.now())/60000));return `<section class="upcoming-review"><h3>下一次延迟回想 · 约 ${minutes} 分钟后</h3><p>${pending.length} 个词已安排短延迟检查，可以先学习下一小组或休息一下。</p>${button('查看复习安排','nav','data-page="review"','secondary')}</section>`;}return ''; }
  function reviewPlan() { const now=Date.now();return `<section class="review-plan"><div class="section-head"><h2>接下来 7 天</h2><span class="muted">包含短延迟与跨日复习</span></div><div class="review-week">${Array.from({length:7},(_,i)=>{const d=C.addDays(C.day(),i),n=all.filter(w=>{const r=state.words[w.id];if(!r)return false;const shortDay=r.delayedDueAt?C.day(new Date(r.delayedDueAt)):null;return i===0?(r.due&&r.due<=d)||(shortDay&&shortDay<=d):r.due===d||shortDay===d;}).length;return `<div class="review-day ${i===0?'today':''}"><span>${i===0?'今天':i===1?'明天':d.slice(5).replace('-','/')}</span><strong>${n}</strong><small>词</small></div>`;}).join('')}</div><p class="help-text">今天的计划包含稍后到时间的延迟复测及逾期词。答题后会更新安排；同一词在同一天只计一次。</p></section>${pendingShort().length?reviewNudge():''}`; }
  function mistakes() { return all.filter(w => state.words[w.id]?.wrong > 0); }
  function completed() { return lists.filter(l => state.lists[l.id]?.completedAt).length; }
  function nextList() { return lists.find(l => !state.lists[l.id]?.completedAt) || lists[29]; }
  function groupProgress(id) { return state.lists[id]?.groups?.length || 0; }
  function plannedDay() { return Math.max(1, Math.min(30, Math.floor((new Date(C.day()+'T12:00:00') - new Date(state.startDate+'T12:00:00')) / 86400000) + 1)); }
  function button(label, action, extra='', cls='primary') { return `<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`; }
  function labelList(id) { return `List ${String(id).padStart(2,'0')}`; }
  function header(title, sub, eyebrow='READING · 每天积累一点') { return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="subtitle">${sub}</p></div></div>`; }
  function shell(content) {
    const active = page === 'detail' || page === 'study' ? 'lists' : page;
    const nav = [['home','home','今日学习'],['lists','book','30 天词表'],['review','review','到期复习'],['mistakes','star','错词本'],['settings','settings','学习设置']];
    app.innerHTML = `<div class="app-shell"><aside class="sidebar"><a class="brand" href="#" data-action="nav" data-page="home"><span class="brand-mark">序</span><span>词序<small>READING 30</small></span></a><nav class="nav" aria-label="主导航">${nav.map(([p,ico,title]) => `<button class="nav-item ${active===p?'active':''}" data-action="nav" data-page="${p}" ${active===p?'aria-current="page"':''}>${icon(ico)}<span>${title}</span>${p==='review'&&dueWords().length?`<span class="tag">${dueWords().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><span class="eyebrow">你的阅读词汇计划</span><strong>${completed()} <span class="muted">/ 30 lists 已完成</span></strong><div class="progress-track"><div class="progress-fill" style="width:${completed()/30*100}%"></div></div><p>认出意思，就是向前一步。</p></div></aside><main class="main"><div class="topbar"><span>IELTS READING VOCABULARY</span><span>${C.day().replaceAll('-',' / ')} <span class="tag">第 ${plannedDay()} 天</span></span></div>${loadError||saveError?`<div class="feedback error" role="alert">${esc(loadError||saveError)}</div>`:''}${content}<footer class="app-footer">词表来自你的原文件 · 学习进度保存在当前浏览器 <button class="text-link" data-action="nav" data-page="settings">备份与说明</button></footer></main></div>`;
  }
  function home() {
    const l = nextList(), n = Object.values(state.words).filter(w=>w.seen).length, due = dueWords().length, ongoing = state.session && !['done'].includes(state.session.phase);
    shell(`${header('今天，练习把词想起来。','一个 list，十个小组。先记忆，再用中文意思检验自己。')}
    ${reviewNudge()}<section class="hero"><div class="hero-copy"><span class="tag">${completed()===30?'30 个 list 已全部完成':'今天推荐 · 接着未完成的学'}</span><h2 class="hero-title">${labelList(l.id)}<br><span>读懂，从这 100 词开始。</span></h2><p class="hero-meta">100 个词 · 10 组 × 10 词 · ${groupProgress(l.id)} / 10 组已通过</p><div class="toolbar">${ongoing?button('继续上次学习 '+icon('arrow'),'resume'):button('开始今日学习 '+icon('arrow'),'open-list',`data-id="${l.id}"`)}${button('查看今日词表','open-list',`data-id="${l.id}"`,'secondary')}</div><p class="help-text">先主动回想中文，再核对。无需默写或拼写。</p></div><div class="hero-art" aria-hidden="true"><div class="hero-orbit"><span>LIST</span><strong>${String(l.id).padStart(2,'0')}</strong><small>READ · RECOGNIZE · REMEMBER</small></div></div></section>
    <div class="stats"><div class="stat"><span class="stat-label">已看过的词</span><strong class="stat-value">${n}<small> / 3,000</small></strong></div><div class="stat"><span class="stat-label">跨日回想成功</span><strong class="stat-value">${Object.values(state.words).filter(w=>w.longTermSuccesses>0).length}<small> 词</small></strong></div><div class="stat"><span class="stat-label">完成的 list</span><strong class="stat-value">${completed()}<small> / 30</small></strong></div><div class="stat"><span class="stat-label">今天待复习</span><strong class="stat-value">${due}<small> 词</small></strong>${due?'<button class="text-link" data-action="nav" data-page="review">去巩固 →</button>':''}</div></div>
    <div class="section-head"><h2>按这个节奏，就很好</h2><span class="muted">进度自动保存，随时回来</span></div><div class="steps"><div class="step"><span class="step-number">01</span><h3>听读音，记意思</h3><p>每次 10 词，听读音、记意思，然后在后面的练习中穿插旧词。</p></div><div class="step"><span class="step-number">02</span><h3>自己回想，再核对</h3><p>选项先隐藏。自己回想中文后再核对，猜对的词也继续复习。</p></div><div class="step"><span class="step-number">03</span><h3>整组检测，再复习</h3><p>约 20 分钟后再回想，隔天继续复测，按记忆表现安排间隔。</p></div></div>
    <div class="section-head"><h2>接下来学什么</h2><button class="text-link" data-action="nav" data-page="lists">全部 30 个 list →</button></div><div class="list-grid">${lists.slice(Math.max(0,l.id-1),Math.min(30,l.id+3)).map(listCard).join('')}</div>`);
  }
  function listCard(l) { const count = groupProgress(l.id), done = state.lists[l.id]?.completedAt; return `<button class="list-card ${done?'completed':''} ${nextList().id===l.id?'current':''}" data-action="open-list" data-id="${l.id}"><span class="list-number">${String(l.id).padStart(2,'0')}</span><span class="tag">${done?'已完成':count?'学习中':'待学习'}</span><h3 class="list-name">${labelList(l.id)}</h3><p class="list-meta">100 词 · ${count} / 10 组通过</p><div class="progress-track"><div class="progress-fill" style="width:${done?100:count*9}%"></div></div><p class="word-preview">${esc(l.words.slice(0,3).map(w=>w.word).join(' · '))}</p></button>`; }
  function listPage() { shell(`${header('30 天，把阅读词汇串起来。','完整保留原表 30 个 list，每组 100 词。可以自由选择，不会因漏学一天而跳过。')}<div class="list-grid">${lists.map(listCard).join('')}</div>`); }
  function detail() {
    const l = lists[selectedList-1], p = C.listState(state,l.id), next = Array.from({length:10},(_,i)=>i).find(i=>!p.groups.includes(i));
    shell(`${header(labelList(l.id),`100 词 · 已通过 ${p.groups.length} / 10 个小组${p.completedAt?' · 整组检测已完成':''}`, '30 天词表 / '+labelList(l.id))}<div class="toolbar">${button(next===undefined?'开始整组检测':'开始第 '+(next+1)+' 组',next===undefined?'final':'group',`data-id="${l.id}" data-group="${next??0}"`)}${button('返回全部词表','nav','data-page="lists"','ghost')}</div><div class="section-head"><h2>先记忆，再测试</h2><span class="muted">每组 10 词，可分几次完成</span></div><div class="group-grid">${Array.from({length:10},(_,i)=>`<button class="group-tile ${p.groups.includes(i)?'completed':''}" data-action="group" data-id="${l.id}" data-group="${i}"><span class="tag">${p.groups.includes(i)?'✓ 已通过':'第 '+(i+1)+' 组'}</span><strong>${i*10+1}—${i*10+10}</strong><small>${esc(l.words[i*10].word)} …</small></button>`).join('')}</div><div class="section-head"><div><h2>整组检测</h2><p class="muted">完成 10 个小组后，随机检查这 100 个词。首次得分与纠错结果分别记录。</p></div>${button(p.completedAt?'重新检测':'开始检测','final',`data-id="${l.id}" ${p.groups.length<10?'disabled':''}`,'secondary')}</div>${p.lastScore!==null?`<div class="feedback success">上次首次正确率 ${p.lastScore}% · 最佳 ${p.bestScore}% · ${p.completedAt?'全部错词已完成纠正':'继续巩固'}</div>`:''}<details class="vocab-preview"><summary>浏览本 list 的 100 个词与中文</summary>${l.words.map(w=>wordRow(w)).join('')}</details>`);
  }
  function wordRow(w,hideMeaning=false) { return `<div class="word-row"><div class="word-row-main"><strong>${esc(w.word)}</strong>${hideMeaning?'':`<span>${esc(w.meaning)}</span>`}${!hideMeaning&&w.note?`<small class="help-text">${esc(w.note)}</small>`:''}${state.words[w.id]?.due?`<small class="review-due">${dueLabel(w.id)}</small>`:''}</div><button class="icon-btn" data-action="speak" data-id="${esc(w.id)}" aria-label="播放 ${esc(w.word)} 读音">${icon('sound')}</button></div>`; }
  function sessionTitle(s) { return s.kind==='group'?`${labelList(s.listId)} · 第 ${s.group+1} 组`:s.kind==='final'?`${labelList(s.listId)} · 整组检测`:s.kind==='review'?'到期复习':'错词巩固'; }
  function quizContent(s,w) {
    const answered=s.selected!==null, correct=s.selected===w.id&&!s.guessed;
    if(!s.recalled&&!answered) return `<div class="recall-card"><span class="tag">先回想 · 选项暂时隐藏</span><h3>在心里说出它的中文意思。</h3><p>给自己几秒钟回想，不需要打字或拼写。</p><div class="card-actions">${button('我想起来了，核对选项','recall')}${button('想不起来，看看答案','unknown','','secondary')}</div></div>`;
    return `<div class="choices">${s.options.map((o,i)=>`<button class="choice ${answered?(o.id===w.id?'correct':o.id===s.selected?'wrong':''):''}" data-action="answer" data-id="${esc(o.id)}" ${answered?'disabled':''}><span class="answer-letter">${String.fromCharCode(65+i)}</span><span>${esc(o.text)}</span>${answered&&o.id===w.id?icon('check'):''}</button>`).join('')}</div>${answered?`<div class="feedback ${correct?'success':'error'}" role="status"><strong>${correct?'核对正确。':s.selected===w.id?'正确意思：'+esc(w.meaning):'再记一下：'+esc(w.word)+' = '+esc(w.meaning)}</strong><p>${correct?'这次练习已记录，延迟复测会继续检查是否记住。':s.guessed?'本次未独立回想出来，按需要复习记录，不会增加熟练度。':'这个词会在本轮结束后重新出现。'}</p>${w.detail&&w.detail!==w.meaning?`<p>${esc(w.detail)}</p>`:''}</div><div class="card-actions">${button(s.index+1===s.ids.length?'查看本轮结果':'下一题 '+icon('arrow'),'quiz-next')}</div>`:`<label class="guess-check"><input type="checkbox" id="guessed" ${s.guessed?'checked':''}> 我是看选项才认出来的 / 不太确定</label><p class="help-text">凭印象猜对的词也会继续复习。键盘 1—4 选择答案。</p>`}`;
  }
  function study() {
    const s=state.session;if(!s){page='home';render();return;}
    if(s.phase==='done'||s.phase==='repair'){result();return;}
    const w=byId.get(s.ids[s.index]),quiz=s.phase==='quiz',answered=s.selected!==null;
    if(quiz&&!s.options){s.options=C.choices(w,[...lists[s.listId-1].words,...all]);persist();}
    const mixed=Math.max(0,s.allIds.length-(s.primaryIds||s.allIds).length);
    const caption=s.round?`第 ${s.round} 轮巩固 · ${s.ids.length} 个待加强的词`:mixed?`本组 ${(s.primaryIds||s.allIds).length} 词 + 穿插 ${mixed} 个旧词，顺序已打乱`:'先尝试自己回想，再核对意思。';
    shell(`${header(sessionTitle(s),caption,quiz?'02 / 主动回想':'01 / 记忆单词')}<div class="session-progress"><span>${quiz?'回想':'记忆'} ${s.index+1} / ${s.ids.length}</span><div class="progress-track"><div class="progress-fill" style="width:${s.index/s.ids.length*100}%"></div></div><button class="text-link" data-action="pause">稍后继续</button></div><div class="study-layout"><section class="study-main"><div class="word-card"><div class="word-label">${quiz?'先想中文，再看选项':'先听读音，再展开中文意思'}</div><h2 class="word">${esc(w.word)}</h2><div class="phonetic">${w.phonetic?'/ '+esc(w.phonetic.replace(/^\/|\/$/g,''))+' /':'点击喇叭听读音'}</div><button class="pronounce" data-action="speak" data-id="${esc(w.id)}">${icon('sound')} 美式读音 <span class="muted">${state.settings.rate===0.75?'慢速':''}</span></button>${((!quiz&&s.revealed)||answered)&&w.note?`<p class="help-text">${esc(w.note)}</p>`:''}${!quiz?(s.revealed?`<div class="meaning">${esc(w.meaning)}</div><div class="word-detail">${w.detail!==w.meaning?esc(w.detail||''):''}</div><div class="card-actions">${button('再听一遍','speak',`data-id="${esc(w.id)}"`,'secondary')}${button(s.index+1===s.ids.length?'开始回想练习 '+icon('arrow'):'记住了，下一个 '+icon('arrow'),'learn-next')}</div>`:`<p class="muted">先在心里想一想，你见过这个词吗？</p><div class="card-actions">${button('展开中文意思','reveal')}</div>`):''}</div>${quiz?quizContent(s,w):''}</section><aside class="study-side"><div class="tag">主动回想 + 延迟复测</div><h3>${quiz?'先自己想，再核对':'读音、词形、意思一起记'}</h3><p>${quiz?'选项暂时隐藏。先在心里说出中文；如果只是猜的，勾选“不太确定”。':'听一遍读音，展开中文，把词和意思联系起来。'}</p><div class="divider"></div><p>本轮练习<br><strong>${s.allIds.length} 个词${mixed?'（含 '+mixed+' 个旧词）':''}</strong></p><p class="help-text">即时练习通过后，约 20 分钟再回想一次，隔天继续复习。只有跨日到期回想成功，才计入“跨日回想成功”。</p><p>快捷键<br><span class="muted">空格：听读音<br>Enter：展开 / 继续<br>1—4：选择答案</span></p></aside></div>`);
  }
  function result() {
    const s=state.session, repair=s.phase==='repair';
    if(repair){s.wrongIds.forEach(id=>C.see(state,id));persist();}
    shell(`${header(sessionTitle(s),repair?'这一轮已经结束。先把不熟悉的词重新记一遍，再做一轮匹配。':'本次词汇已全部答对，包含答错后重新记忆和测试的词。',repair?'再巩固一次':'这一步，完成了')}<section class="result-card"><span class="tag">${s.round===0?'首次测试':'纠错后的结果'}</span><div class="result-score">${s.firstScore}<span>%</span></div><p>首次独立回想正确率 · ${s.allIds.length} 个词</p>${repair?`<h2>还有 ${s.wrongIds.length} 个词需要加强</h2><p class="muted">答错不是白学，它告诉你下一遍应该看哪里。</p><div class="toolbar">${button('重新记忆这 '+s.wrongIds.length+' 词','retry')}${button('稍后继续','pause','','ghost')}</div>`:`<h2>${s.kind==='final'?'这个 list 的当日练习完成了。':'本轮练习通过了。'}</h2><p class="muted">${s.round?`经过 ${s.round} 轮巩固，所有词已答对。`:'所有词均在本轮独立回想并核对正确。'}接下来还会做延迟与跨日复测。</p><p class="help-text">短延迟检查：约 20 分钟后（以复习页安排为准）</p><p class="help-text">跨日复习日期：${esc([...new Set(s.allIds.map(id=>state.words[id]?.due).filter(Boolean))].sort().join('、'))}</p><div class="toolbar">${button(s.kind==='group'?'继续这个 list':'回到今日学习','finish-session')}${button('去到期复习','nav','data-page="review"','secondary')}</div>`}</section>${repair?`<div class="section-head"><h2>本轮待加强</h2></div>${s.wrongIds.map(id=>wordRow(byId.get(id))).join('')}`:''}`);
  }
  function collection(kind) {
    if(kind==='mistakes'){mistakes().forEach(w=>C.see(state,w.id));persist();}
    const list = C.reviewQueue(state, kind==='review'?dueWords():mistakes());
    const filtered = list.filter(w=>(w.word+' '+w.meaning).toLowerCase().includes(searchText.toLowerCase()));
    const title = kind==='review'?'让昨天的词，留到明天。':'错过的词，再认识一遍。';
    const sub = kind==='review'?`今天有 ${list.length} 个词到期。每次最多 20 词，先回想再核对。下面暂不显示中文，避免提前看到答案。`:`共 ${list.length} 个曾答错的词。错词记录会保留，便于反复巩固。`;
    shell(`${header(title,sub,kind==='review'?'SPACED REVIEW · 到期复习':'WORD NOTEBOOK · 错词本')}${kind==='review'?reviewPlan():''}<div class="toolbar">${button(kind==='review'?'开始复习（最多 20 词）':'巩固错词（最多 20 词）','collection-start',`data-kind="${kind==='review'?'review':'mistakes'}" ${list.length?'':'disabled'}`)}<label class="search"><span class="sr-only">搜索英文或中文</span><input id="search" type="search" placeholder="搜索英文或中文" value="${esc(searchText)}" autocomplete="off"></label></div><div id="collection-rows">${collectionRows(filtered,list.length,kind)}</div>`);
  }
  function collectionRows(filtered,total,kind) { return filtered.length?filtered.map(w=>wordRow(w,kind==='review')).join(''):`<div class="empty">${icon(kind==='review'?'review':'star')}<h2>${total?'没有找到这个词':kind==='review'?'今天暂时没有到期词':'还没有错词记录'}</h2><p>${total?'试试另一个英文或中文关键词。':kind==='review'?'延迟复测尚未到时间时，可以先学下一小组。稍后回来刷新复习列表。':'先开始一个小组，答错的词会自动收进这里。'}</p>${button('开始学习','nav','data-page="home"','secondary')}</div>`; }
  function settings() {
    shell(`${header('按你的节奏来。','学习数据保存在当前浏览器。导出备份可以转移到另一台设备。','PREFERENCES · 学习设置')}<section class="settings-card"><div class="settings-row"><div><h3>学习开始日期</h3><p>用于显示 30 天计划，不会锁定或跳过任何 list。</p></div><input id="start-date" type="date" value="${esc(state.startDate)}" aria-label="学习开始日期"></div><div class="settings-row"><div><h3>读音速度</h3><p>内置 Emma 自然美式读音，可反复听。</p></div><select id="rate" aria-label="读音速度"><option value="0.75" ${state.settings.rate===0.75?'selected':''}>慢速 · 0.75×</option><option value="1" ${state.settings.rate===1?'selected':''}>正常 · 1×</option><option value="1.15" ${state.settings.rate===1.15?'selected':''}>稍快 · 1.15×</option></select></div><div class="settings-row"><div><h3>进度备份</h3><p>更换设备或清理浏览器前，请先导出；不同设备不会自动同步。</p></div><div class="toolbar">${button('导出进度','export','','secondary')}${button('导入进度','import','','secondary')}<input type="file" id="import-file" accept="application/json,.json" hidden></div></div><div class="settings-row"><div><h3>重新开始</h3><p>清除本浏览器的学习记录。建议先导出备份。</p></div>${button('清空学习记录','reset','','danger')}</div></section><section class="about-card"><h2>词表与学习方式</h2><p>你的原表包含 30 个 list，共 3,000 个不同的词。软件保留原有分组与顺序；每 10 词先记忆、再测试，10 组都通过后开放 100 词整组检测。</p><p>中文释义以 <a href="https://github.com/skywind3000/ECDICT" target="_blank" rel="noopener">ECDICT 开源英汉词典</a>为基础，另对缺失词、明显异常词义和部分词形补充整理。中文是常见义，阅读文章中的具体含义仍需结合上下文。原表疑似拼写问题会提示，专名和少数生僻词的合成读音可在词典中复核。</p><p>新词即时练习只算当日练习。每组测试穿插最多 3 个旧词，选项先隐藏；不确定的答案按需要复习处理。首次练习后约 20 分钟再检查，跨日到期且距最近看过释义至少 8 小时的成功回想，才计入“跨日回想成功”。这些时间是软件默认的练习安排，不是每个人固定的遗忘节点。</p><p>跨日复习使用基于 <a href="https://super-memory.com/english/ol/sm2.htm" target="_blank" rel="noopener">SM-2</a> 的自适应间隔：新词首次答对后 1 天复习，跨日到期复习再答对后间隔 6 天，之后按该词难度逐步延长（例如 15 天、38 天）。答错立即重新记忆并重测，纠正后明天再复习。同一天反复答对或未到期提前练习不会拉长间隔。它利用间隔重复应对遗忘，不代表精确测得你的个人遗忘曲线。首次正确率保留首次表现，不会被纠错后的得分覆盖。</p><p>音频为内置 Emma 自然美式神经语音合成，并非真人录音。音标沿用词库，可能与美式读音存在英美差异。读音文件无法播放时，会尝试浏览器英语朗读。</p><p>建议每天完成一个 list，可拆成多次学习。首页始终推荐尚未完成的 list，避免因漏学而跳过。</p></section>`);
  }
  function render() { if(page==='home')home();else if(page==='lists')listPage();else if(page==='detail')detail();else if(page==='study')study();else if(page==='settings')settings();else collection(page); }
  function stopAudio() { audioToken++; if(audio){audio.pause();audio=null;} if(window.speechSynthesis) speechSynthesis.cancel(); }
  async function speak(id) {
    const w = byId.get(id); if(!w)return;
    stopAudio(); const token=audioToken;
    audio = new Audio('audio/'+encodeURIComponent(w.id)+'.mp3?v=20261030-emma'); audio.playbackRate=state.settings.rate;
    try { await audio.play(); }
    catch(e) { if(token!==audioToken)return; if(window.speechSynthesis && window.SpeechSynthesisUtterance){const voices=speechSynthesis.getVoices();const voice=voices.find(v=>v.lang==='en-US')||voices.find(v=>v.lang.startsWith('en'));if(!voice){notify('读音暂时无法播放，请检查 audio 文件夹是否完整，或换用 Edge / Chrome。');return;} const u=new SpeechSynthesisUtterance(w.word==='immunoglobin'?'immunoglobulin':w.word);u.lang='en-US';u.voice=voice;u.rate=state.settings.rate;u.onerror=()=>notify('朗读未成功，请检查设备声音设置。');speechSynthesis.speak(u);}else notify('读音暂时无法播放，请检查 audio 文件夹是否完整。'); }
  }
  function modal(title, body, confirmLabel, onConfirm) {
    const old=document.querySelector('.modal-backdrop'); if(old)old.remove();
    const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${esc(title)}</h2><p>${esc(body)}</p><div class="dialog-actions"><button class="btn secondary" id="modal-cancel">取消</button><button class="btn primary" id="modal-confirm">${esc(confirmLabel)}</button></div></section>`;document.body.append(wrap);
    const previous=document.activeElement; const close=()=>{wrap.remove();previous?.focus();};wrap.querySelector('#modal-cancel').onclick=close;wrap.querySelector('#modal-confirm').onclick=()=>{close();onConfirm();};wrap.querySelector('#modal-cancel').focus();wrap.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const bs=wrap.querySelectorAll('button');if(e.shiftKey&&document.activeElement===bs[0]){e.preventDefault();bs[1].focus();}else if(!e.shiftKey&&document.activeElement===bs[1]){e.preventDefault();bs[0].focus();}}});
  }
  function launch(kind,listId,group,ids,phase='learn') {
    const go=()=>{stopAudio();state.session=C.makeSession(kind,listId,group,ids,phase);persist();page='study';render();window.scrollTo(0,0);};
    if(state.session && !['done'].includes(state.session.phase)) modal('开始新的学习？','上一次的小组还未完成。已做过的词汇记录会保留，但当前小组将重新开始。','开始新的学习',go);else go();
  }
  function recordVisibleMeanings() {
    const s=state.session;
    if(page==='study'&&s&&((s.phase==='learn'&&s.revealed)||(s.phase==='quiz'&&s.selected!==null))) C.see(state,s.ids[s.index]);
    if(page==='study'&&s?.phase==='repair') s.wrongIds.forEach(id=>C.see(state,id));
    if(page==='mistakes') mistakes().forEach(w=>C.see(state,w.id));
    if(page==='detail'&&document.querySelector('.vocab-preview[open]')) lists[selectedList-1].words.forEach(w=>C.see(state,w.id));
  }
  app.addEventListener('click',e=>{
    const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();const a=el.dataset.action,id=el.dataset.id,s=state.session;
    recordVisibleMeanings();persist();
    if(a==='speak'){speak(id);return;}
    if(a==='nav'){stopAudio();page=el.dataset.page;searchText='';render();window.scrollTo(0,0);return;}
    if(a==='open-list'){stopAudio();selectedList=Number(id);page='detail';render();window.scrollTo(0,0);return;}
    if(a==='group'){const n=Number(id),g=Number(el.dataset.group);launch('group',n,g,lists[n-1].words.slice(g*10,g*10+10).map(w=>w.id));return;}
    if(a==='final'){const n=Number(id);if(groupProgress(n)<10)return;launch('final',n,0,lists[n-1].words.map(w=>w.id),'quiz');return;}
    if(a==='collection-start'){const kind=el.dataset.kind;let words=kind==='review'?dueWords():mistakes();words=C.reviewQueue(state,words);if(words.length)launch(kind,Number(words[0].id.split('-')[0]),0,words.slice(0,20).map(w=>w.id),kind==='review'?'quiz':'learn');return;}
    if(a==='resume'){page='study';render();return;}
    if(a==='pause'){stopAudio();page='home';persist();render();return;}
    if(a==='reveal'&&s?.phase==='learn'){s.revealed=true;C.see(state,s.ids[s.index]);persist();render();return;}
    if(a==='learn-next'&&s?.phase==='learn'&&s.revealed){stopAudio();C.see(state,s.ids[s.index]);if(s.index+1<s.ids.length){s.index++;s.revealed=false;}else {const extra=s.kind==='group'&&s.round===0?C.shuffle(all.filter(w=>state.words[w.id]?.seen&&!s.allIds.includes(w.id))).sort((a,b)=>Number(C.isDue(state,b.id))-Number(C.isDue(state,a.id))||(state.words[a.id].lastSeenAt||0)-(state.words[b.id].lastSeenAt||0)).slice(0,3).map(w=>w.id):[];C.beginQuiz(s,extra);}persist();render();return;}
    if(a==='recall'&&s?.phase==='quiz'&&s.selected===null){s.recalled=true;persist();render();return;}
    if(a==='answer'&&s?.recalled&&C.submit(state,id,s.guessed===true)){C.see(state,s.ids[s.index]);persist();render();return;}
    if(a==='unknown'&&s?.phase==='quiz'&&s.selected===null){s.recalled=true;C.submit(state,s.ids[s.index],true);C.see(state,s.ids[s.index]);persist();render();return;}
    if(a==='quiz-next'&&s?.phase==='quiz'&&s.selected!==null){stopAudio();if(s.index+1<s.ids.length){s.index++;s.selected=null;s.options=null;s.recalled=false;s.guessed=false;}else C.finish(state);persist();render();return;}
    if(a==='retry'&&s?.phase==='repair'){C.retry(s);persist();render();return;}
    if(a==='finish-session'&&s?.phase==='done'){selectedList=s.listId;page=s.kind==='group'?'detail':'home';state.session=null;persist();render();window.scrollTo(0,0);return;}
    if(a==='export'){const blob=new Blob([JSON.stringify({app:'reading30',exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='词序学习进度-'+C.day()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('备份文件已导出。');return;}
    if(a==='import'){document.getElementById('import-file').click();return;}
    if(a==='reset'){modal('清空学习记录？','此操作会清除当前浏览器的进度和错词。已经导出的备份不会受影响。','确认清空',()=>{stopAudio();loadError='';state=C.fresh();persist();render();notify('已开始新的学习计划。');});return;}
  });
  app.addEventListener('change',async e=>{
    if(e.target.id==='guessed'&&state.session?.phase==='quiz'&&state.session.selected===null){state.session.guessed=e.target.checked;persist();return;}
    if(e.target.id==='start-date'){if(C.validDay(e.target.value)){state.startDate=e.target.value;persist();render();}return;}
    if(e.target.id==='rate'){const r=Number(e.target.value);if([0.75,1,1.15].includes(r)){state.settings.rate=r;persist();notify('读音速度已更新。');}return;}
    if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024){notify('备份文件过大，请选择词序导出的 JSON 文件。');return;}try{const data=JSON.parse(await file.text());if(data.app!=='reading30')throw new Error('请选择词序导出的进度文件。');const restored=C.validate(data.state,known);modal('导入这份学习进度？','导入将替换当前浏览器进度。建议先导出当前进度作为备份。','确认导入',()=>{stopAudio();loadError='';state=restored;persist();render();notify('进度已恢复。');});}catch(err){notify(err.message||'无法读取这份备份。');}e.target.value='';}
  });
  app.addEventListener('toggle',e=>{if(e.target.matches('.vocab-preview')){lists[selectedList-1].words.forEach(w=>C.see(state,w.id));persist();}},true);
  app.addEventListener('input',e=>{if(e.target.id==='search'){searchText=e.target.value;const source=page==='review'?dueWords():mistakes();document.getElementById('collection-rows').innerHTML=collectionRows(source.filter(w=>(w.word+' '+w.meaning).toLowerCase().includes(searchText.toLowerCase())),source.length,page);}});
  document.addEventListener('keydown',e=>{if(document.querySelector('.modal-backdrop')||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)||page!=='study')return;const s=state.session;if(!s||!['learn','quiz'].includes(s.phase))return;if(e.code==='Space'){e.preventDefault();speak(s.ids[s.index]);}else if(e.key==='Enter'&&document.activeElement?.tagName!=='BUTTON'){e.preventDefault();const action=s.phase==='learn'?(s.revealed?'learn-next':'reveal'):(s.selected!==null?'quiz-next':!s.recalled?'recall':null);if(action)app.querySelector(`[data-action="${action}"]`)?.click();}else if(/^[1-4]$/.test(e.key)&&s.phase==='quiz'&&s.recalled&&s.selected===null){app.querySelectorAll('[data-action="answer"]')[Number(e.key)-1]?.click();}});
  window.addEventListener('pagehide',()=>{recordVisibleMeanings();persist();stopAudio();});
  setInterval(()=>{if(!document.hidden&&['home','review'].includes(page)&&document.activeElement?.id!=='search'&&!document.querySelector('.modal-backdrop'))render();},30000);
  window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=C.validate(JSON.parse(e.newValue),known);stopAudio();render();notify('已同步同一浏览器另一个窗口的进度。');}catch(err){}}});
  render();
})();
